import{_ as p,r as a,o,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const h=JSON.parse('{"title":"{% for %} - October CMS - 3.x","titleTemplate":false,"description":"Twig-тег","frontmatter":{"subtitle":"Twig-тег"},"headers":[{"level":2,"title":"Итерация по коллекции","slug":"итерация-по-коллекции","link":"#итерация-по-коллекции","children":[]},{"level":2,"title":"Добавление условия","slug":"добавление-условия","link":"#добавление-условия","children":[]},{"level":2,"title":"Переменная loop","slug":"переменная-loop","link":"#переменная-loop","children":[]}],"relativePath":"3.x/ru/markup/tag/for.md","filePath":"3.x/ru/markup/tag/for.md"}'),u={name:"3.x/ru/markup/tag/for.md"};function g(r,n,k,d,m,w){const t=a("pre-heading"),e=a("post-heading");return o(),l("div",null,[s(t),n[0]||(n[0]=c("h1",null,"{% for %}",-1)),s(e),n[1]||(n[1]=i(`<p>Теги <code>{% for %}</code> и <code>{% endfor %}</code> выполняют итерацию по каждому значению в коллекции. Коллекция может быть массивом или объектом, реализующим интерфейс <code>Traversable</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Вы также можете получить доступ и к ключам, и к значениям:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> key<span class="token punctuation">,</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> key <span class="token delimiter punctuation">}}</span></span>: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Если коллекция пуста, можно отобразить альтернативный блок с помощью else:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>em</span><span class="token punctuation">&gt;</span></span>There are no users found<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>em</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="итерация-по-коллекции"><a href="#итерация-по-коллекции" class="header-anchor">#</a> Итерация по коллекции</h2><p>Если вам нужно выполнить итерацию по коллекции чисел, можно использовать оператор <code>..</code>:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> i <span class="token operator">in</span> <span class="token number">0.</span><span class="token number">.10</span> <span class="token delimiter punctuation">%}</span></span>
    - <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> i <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Приведённый выше фрагмент кода выведет все числа от 0 до 10.</p><p>Это также полезно для букв:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> letter <span class="token operator">in</span> <span class="token string"><span class="token punctuation">&#39;</span>a<span class="token punctuation">&#39;</span></span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token string"><span class="token punctuation">&#39;</span>z<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
    - <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> letter <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Оператор <code>..</code> принимает любое выражение с обеих сторон:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> letter <span class="token operator">in</span> <span class="token string"><span class="token punctuation">&#39;</span>a<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>upper<span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token string"><span class="token punctuation">&#39;</span>z<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>upper <span class="token delimiter punctuation">%}</span></span>
    - <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> letter <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="добавление-условия"><a href="#добавление-условия" class="header-anchor">#</a> Добавление условия</h2><p>В отличие от PHP, в цикле нет функции <code>break</code> или <code>continue</code>, однако вы можете фильтровать коллекцию. Следующий пример пропускает всех <code>users</code>, которые не активны.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> user<span class="token punctuation">.</span>active <span class="token delimiter punctuation">%}</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="переменная-loop"><a href="#переменная-loop" class="header-anchor">#</a> Переменная loop</h2><p>Внутри блока цикла <code>for</code> вы можете обращаться к некоторым специальным переменным:</p><div class="table"><table tabindex="0"><thead><tr><th>Переменная</th><th>Описание</th></tr></thead><tbody><tr><td><code>loop.index</code></td><td>Текущая итерация цикла (начиная с 1)</td></tr><tr><td><code>loop.index0</code></td><td>Текущая итерация цикла (начиная с 0)</td></tr><tr><td><code>loop.revindex</code></td><td>Количество итераций до конца цикла (начиная с 1)</td></tr><tr><td><code>loop.revindex0</code></td><td>Количество итераций до конца цикла (начиная с 0)</td></tr><tr><td><code>loop.first</code></td><td>True, если первая итерация</td></tr><tr><td><code>loop.last</code></td><td>True, если последняя итерация</td></tr><tr><td><code>loop.length</code></td><td>Количество элементов в коллекции</td></tr><tr><td><code>loop.parent</code></td><td>Родительский контекст</td></tr></tbody></table></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> loop<span class="token punctuation">.</span>index <span class="token delimiter punctuation">}}</span></span> - <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div>`,21))])}const v=p(u,[["render",g]]);export{h as __pageData,v as default};
